//! Font sets of fonts generated by a test.

use std::borrow::Cow;

use text_mesh_font::{FontAsset, FontSet, Glyph, GlyphMetrics, GlyphRect, SpriteAsset};

/// Uses the first entry in `fonts` as primary, then `global_fallbacks`; missing glyphs render as `?` when sprites are unavailable.
#[must_use]
pub fn font_set(fonts: Vec<FontAsset>, global_fallbacks: &[usize]) -> FontSet {
    FontSet {
        fonts: Cow::Owned(fonts),
        primary: 0,
        global_fallbacks: Cow::Owned(global_fallbacks.to_vec()),
        missing_glyph: '?',
        sprites: SpriteAsset::default(),
    }
}

/// Font `name` of the glyphs of `characters`, each `advance` wide, falling back to `fallbacks`; otherwise default.
#[must_use]
pub fn font(name: &'static str, characters: &str, advance: f32, fallbacks: &[usize]) -> FontAsset {
    FontAsset {
        name: Cow::Borrowed(name),
        fallbacks: Cow::Owned(fallbacks.to_vec()),
        ..FontAsset::default()
    }
    .with_glyphs(characters.chars().map(|character| Glyph {
        character,
        metrics: GlyphMetrics {
            advance,
            ..GlyphMetrics::default()
        },
        rect: GlyphRect::default(),
    }))
}
